class Solution {
  public long maxTotal(int[] nums, String s) {
    int n = nums.length;
    long NEG = Long.MIN_VALUE / 4;
    long[] dp = {
      0, NEG
    }; // dp[u]: the token at the current index has (1) or has not (0) been used for index - 1
    for (int i = 0; i < n; i++) {
      long[] nd = {NEG, NEG};
      for (int u = 0; u < 2; u++) {
        if (dp[u] == NEG) continue;
        // leave index i uncovered
        nd[0] = Math.max(nd[0], dp[u]);
        // cover index i with the token sitting there (it stays)
        if (s.charAt(i) == '1' && u == 0) nd[0] = Math.max(nd[0], dp[u] + nums[i]);
        // cover index i with the token from i + 1
        if (i + 1 < n && s.charAt(i + 1) == '1') nd[1] = Math.max(nd[1], dp[u] + nums[i]);
      }
      dp = nd;
    }
    return Math.max(dp[0], dp[1]);
  }
}
